/* Creator website blogs (lib/site-blog). Six tables, each keyed by the store (creator_id), so a blog outlives a theme switch: site_blog_settings (the blog's address, previous addresses answered with a 308, title, description, posts per page, search and share details), site_blog_authors, site_blog_categories, site_blog_posts (the LIVE columns visitors read, written only by Publish/Update, and the WORKING copy draft_meta/draft_content every autosave writes; status draft, published or archived, a published post with a date ahead is scheduled and goes live by itself with no job; version for the editor's 409; summary, the opening words the cards show), site_blog_post_revisions (fifty kept per post) and site_blog_redirects (an old post address to the new one). Row level security on every table, four policies each for the store's owner; nothing granted to anon: visitors read through the server, filtered by creator_id, live columns only. Until it runs the Blog screen says it is waiting for this part and every site draws exactly as before. No existing rows change. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.site_blog_settings (creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE, handle text NOT NULL DEFAULT 'news' CHECK (handle ~ '^[a-z0-9][a-z0-9-]{0,62}$'), previous_handles text[] NOT NULL DEFAULT '{}', title text NOT NULL DEFAULT 'Blog' CHECK (char_length(title) <= 120), description text NOT NULL DEFAULT '' CHECK (char_length(description) <= 1000), posts_per_page int NOT NULL DEFAULT 12 CHECK (posts_per_page BETWEEN 1 AND 48), seo_title text, seo_description text, og_image_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.site_blog_authors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, slug text NOT NULL CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 120), role text, bio text, avatar_url text, links jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (creator_id, slug));
CREATE TABLE IF NOT EXISTS public.site_blog_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, slug text NOT NULL CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80), description text NOT NULL DEFAULT '', sort_order int NOT NULL DEFAULT 0, seo_title text, seo_description text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (creator_id, slug));
CREATE TABLE IF NOT EXISTS public.site_blog_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','archived')), slug text NOT NULL CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND char_length(slug) <= 120), title text NOT NULL DEFAULT '', excerpt text NOT NULL DEFAULT '', summary text NOT NULL DEFAULT '', content jsonb NOT NULL DEFAULT '[]', cover_image_url text, cover_alt text, category_id uuid REFERENCES public.site_blog_categories(id) ON DELETE SET NULL, tags text[] NOT NULL DEFAULT '{}', author_id uuid REFERENCES public.site_blog_authors(id) ON DELETE SET NULL, seo_title text, seo_description text, canonical_url text, og_title text, og_description text, og_image_url text, noindex boolean NOT NULL DEFAULT false, featured boolean NOT NULL DEFAULT false, word_count int NOT NULL DEFAULT 0, reading_minutes int NOT NULL DEFAULT 0, published_at timestamptz, first_published_at timestamptz, content_updated_at timestamptz, draft_meta jsonb, draft_content jsonb, draft_saved_at timestamptz, version int NOT NULL DEFAULT 1, created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (creator_id, slug));
CREATE INDEX IF NOT EXISTS site_blog_posts_live_idx ON public.site_blog_posts (creator_id, published_at DESC) WHERE status = 'published';
CREATE INDEX IF NOT EXISTS site_blog_posts_admin_idx ON public.site_blog_posts (creator_id, status, updated_at DESC);
CREATE INDEX IF NOT EXISTS site_blog_posts_category_idx ON public.site_blog_posts (creator_id, category_id);
CREATE INDEX IF NOT EXISTS site_blog_posts_tags_idx ON public.site_blog_posts USING gin (tags);
CREATE TABLE IF NOT EXISTS public.site_blog_post_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.site_blog_posts(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, kind text NOT NULL CHECK (kind IN ('save','publish','update','schedule','unpublish','restore')), meta jsonb NOT NULL, content jsonb NOT NULL, created_by uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS site_blog_post_revisions_post_idx ON public.site_blog_post_revisions (post_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.site_blog_redirects (creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, from_slug text NOT NULL CHECK (char_length(from_slug) BETWEEN 1 AND 200), to_slug text NOT NULL CHECK (char_length(to_slug) BETWEEN 1 AND 200), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (creator_id, from_slug));
CREATE OR REPLACE FUNCTION public.site_blog_touch() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at := now(); RETURN NEW; END $$;
DROP TRIGGER IF EXISTS site_blog_settings_touch ON public.site_blog_settings;
CREATE TRIGGER site_blog_settings_touch BEFORE UPDATE ON public.site_blog_settings FOR EACH ROW EXECUTE FUNCTION public.site_blog_touch();
DROP TRIGGER IF EXISTS site_blog_authors_touch ON public.site_blog_authors;
CREATE TRIGGER site_blog_authors_touch BEFORE UPDATE ON public.site_blog_authors FOR EACH ROW EXECUTE FUNCTION public.site_blog_touch();
DROP TRIGGER IF EXISTS site_blog_categories_touch ON public.site_blog_categories;
CREATE TRIGGER site_blog_categories_touch BEFORE UPDATE ON public.site_blog_categories FOR EACH ROW EXECUTE FUNCTION public.site_blog_touch();
DROP TRIGGER IF EXISTS site_blog_posts_touch ON public.site_blog_posts;
CREATE TRIGGER site_blog_posts_touch BEFORE UPDATE ON public.site_blog_posts FOR EACH ROW EXECUTE FUNCTION public.site_blog_touch();
ALTER TABLE public.site_blog_settings ENABLE ROW LEVEL SECURITY;
DO $p$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='site_blog_settings' AND policyname='site_blog_settings_select_own') THEN CREATE POLICY site_blog_settings_select_own ON public.site_blog_settings FOR SELECT TO authenticated USING (creator_id IN (SELECT id FROM public.creators WHERE user_id = auth.uid())); END IF; END $p$;
DO $p$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='site_blog_settings' AND policyname='site_blog_settings_insert_own') THEN CREATE POLICY site_blog_settings_insert_own ON public.site_blog_settings FOR INSERT TO authenticated WITH CHECK (creator_id IN (SELECT id FROM public.creators WHERE user_id = auth.uid())); END IF; END $p$;
DO $p$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='site_blog_settings' AND policyname='site_blog_settings_update_own') THEN CREATE POLICY site_blog_settings_update_own ON public.site_blog_settings FOR UPDATE TO authenticated USING (creator_id IN (SELECT id FROM public.creators WHERE user_id = auth.uid())) WITH CHECK (creator_id IN (SELECT id FROM public.creators WHERE user_id = auth.uid())); END IF; END $p$;
DO $p$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='site_blog_settings' AND policyname='site_blog_settings_delete_own') THEN CREATE POLICY site_blog_settings_delete_own ON public.site_blog_settings FOR DELETE TO authenticated USING (creator_id IN (SELECT id FROM public.creators WHERE user_id = auth.uid())); END IF; END $p$;
REVOKE ALL ON public.site_blog_settings FROM PUBLIC, anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.site_blog_settings TO authenticated;
GRANT ALL ON public.site_blog_settings TO service_role;
